  our_subject: s(b.our_subject, 200), our_body: s(b.our_body, 3000), reply_from: s(b.reply_from, 200), reply_subject: s(b.reply_subject, 200), reply_text: text, received_at: s(b.received_at, 40), urls } }];

// The pages to check for our link: URLs on the prospect's site named in the reply, and the page we pitched.
const r = $('Reply Input').first().json;
return r.ok && r.urls.length ? r.urls.map(url => ({ json: { url } })) : [{ json: { skip: true } }];

// The reply for the Reply Reader, with what the link check found (a reply saying "done" is believed only when the link is on the page).
// ---- link kit (v4.10, inlined by build_monitors.py): reads a fetched page the way a link checker does — the links to a site with their rel,
// anchor and placement, page facts (noindex, canonical, outbound links, language) and contact e-mails. Regex only: the n8n sandbox has no URL
